import queue

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Return how many elements of xs were accepted by a bounded queue.

    The queue holds at most cap items. Each element of xs is offered with a
    non-blocking put in order. Counting stops at the first put that is
    rejected because the queue is full. A capacity of 0 accepts nothing.
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_accepted_stops_when_full() -> None:
    assert accepted(2, [1, 2, 3]) == 2


def test_accepted_all_fit() -> None:
    assert accepted(5, [1, 2]) == 2


def test_accepted_empty_input() -> None:
    assert accepted(3, []) == 0


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_exact_capacity() -> None:
    assert accepted(3, [7, 8, 9]) == 3


@pytest.mark.parametrize(
    ("cap", "xs", "expected"),
    [
        (1, [10], 1),
        (1, [10, 20], 1),
        (4, [1, 2, 3, 4, 5, 6], 4),
    ],
)
def test_accepted_parametrized(cap: int, xs: list[int], expected: int) -> None:
    assert accepted(cap, xs) == expected
